<template><section class="log-page" v-loading="loading"><h2>{{titles[kind]}}</h2><div v-if="logDetailLoading" role="status">正在加载日志详情…<el-button link type="primary" @click="invalidateLogDetail">取消详情加载</el-button></div><template v-if="kind==='config'"><el-form label-width="180px"><el-form-item v-for="f in configFields" :key="f.key" :label="f.label"><el-input-number v-model="config[f.key]" :min="1" :max="f.key.endsWith('Ms')?600000:3650"/></el-form-item><el-form-item label="启用自动归档清理"><el-switch v-model="config.cleanupEnabled"/></el-form-item></el-form><p>待投递：{{config.pending}}　重试中：{{config.failedDeliveries}}　运行日志：{{config.runtimeCollected}}</p><p>最老待投递：{{displayDateTime(config.oldestPendingTime)}}　等待：{{config.oldestPendingSeconds||0}}秒　最近一分钟投递：{{config.deliveredLastMinute||0}}</p><el-button v-if="can('monitor:log-config:edit')" type="primary" @click="saveConfig">保存配置</el-button><h3>清理执行记录</h3><el-table :data="history" border><el-table-column label="日期" prop="businessDate"/><el-table-column label="结果" prop="status"/><el-table-column label="阶段" prop="stage"/><el-table-column label="操作日志已清理" prop="operationCount"/><el-table-column label="登录日志已清理" prop="loginCount"/><el-table-column label="运行日志已清理" prop="runtimeCount"/><el-table-column label="队列已清理" prop="outboxCount"/><el-table-column label="说明" prop="summary"/></el-table></template><template v-else><div class="log-toolbar filter-toolbar-card" role="search" aria-label="日志筛选"><div class="filters"><el-select v-if="kind==='operation'&&admin" v-model="query.factoryId" clearable aria-label="工厂" placeholder="工厂" @change="actorFactoryChanged"><el-option v-for="f in factories" :key="f.id" :label="f.name" :value="f.id"/></el-select><el-select v-if="kind==='operation'||kind==='login'" v-model="query.actorId" class="log-actor-select" :aria-label="kind==='login'?'登录人员':'操作人员'" clearable filterable remote :remote-method="searchActors" :loading="actorsLoading" :placeholder="kind==='login'?'登录人员（角色／姓名／手机号）':'操作人员（角色／姓名／手机号）'" @visible-change="v=>v&&searchActors('')"><el-option v-for="person in actorOptions" :key="person.id" :label="person.name" :value="person.id"/><template v-if="actorsMore" #footer><el-button link type="primary" :loading="actorsLoading" @click="searchActors(actorKeyword,true)">加载更多</el-button></template></el-select><el-input v-if="kind==='operation'" v-model="query.module" placeholder="模块"/><el-select v-if="kind==='operation'" v-model="query.resultCode" clearable placeholder="结果"><el-option v-for="(name,value) in results" :key="value" :label="name" :value="value"/></el-select><el-input v-if="kind==='operation'" v-model="query.businessCode" placeholder="业务单号"/><el-select v-if="kind==='runtime'" v-model="query.level" clearable placeholder="日志级别"><el-option v-for="v in ['INFO','WARN','ERROR']" :key="v" :label="v" :value="v"/></el-select><el-input v-if="kind==='runtime'" v-model="query.component" placeholder="组件"/><el-select v-if="kind==='login'" v-model="query.associationStatus" clearable placeholder="关联状态"><el-option label="已关联" value="LINKED"/><el-option label="历史未关联" value="HISTORICAL"/><el-option label="账号未识别" value="UNIDENTIFIED"/></el-select><el-input v-model="query.traceId" placeholder="追踪ID"/><el-date-picker class="log-filter-date" v-model="range" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" popper-class="filter-toolbar-date-panel" start-placeholder="开始时间" end-placeholder="结束时间"/></div><div class="filter-action-group"><el-button class="filter-query-button" type="primary" @click="applyFilters">查询</el-button><el-button @click="resetFilters">重置</el-button></div><el-button class="filter-export-button" type="primary" plain v-if="can(exportPermission)" :loading="exporting" :disabled="loading||!loadedFilters" @click="exportLogs">导出</el-button></div><p v-if="kind==='login'&&query.actorId">人员筛选仅包含已可靠关联的记录；旧记录请清空人员并选择“历史未关联”查询。</p><el-table :data="rows" border><el-table-column v-for="c in columns" :key="c.key" :label="c.label" :prop="c.key" :min-width="c.width||110"><template #default="{row}">{{c.key==='associationStatus'?associationNames[row[c.key]]||'—':c.key==='resultCode'?results[row[c.key]]||row[c.key]:kind==='login'&&c.key==='status'?(row[c.key]==='0'?'成功':'失败'):c.key.endsWith('Time')?displayDateTime(row[c.key]):row[c.key]??'—'}}</template></el-table-column><el-table-column v-if="kind!=='login'&&can(detailPermission)" label="操作" width="85"><template #default="{row}"><el-button link type="primary" :loading="logDetailLoading&&String(logDetailTargetId)===String(row.id||row.operId)" @click="view(row)">详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.pageNum" :page-size="16" :total="total" layout="total,prev,pager,next" @current-change="load"/></template><el-dialog v-model="detailOpen" title="日志详情" width="min(950px,94vw)"><p v-if="logDetailLoading">日志详情加载中…</p><div class="log-details" v-else><template v-for="(value,key) in detail" :key="key"><strong>{{fieldNames[key]||key}}</strong><pre>{{format(String(key).endsWith('Time')?displayDateTime(value):value)}}</pre></template></div><template #footer><el-button :disabled="logDetailLoading||!detail.traceId" @click="copyTrace">复制追踪ID</el-button><el-button @click="detailOpen=false">关闭</el-button></template></el-dialog></section></template>
<script setup lang="ts">
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission=useActionPermission()
import {displayDateTime} from '@/utils/display-date-time'
import {copyText} from '@/utils/clipboard'
import{computed,onMounted,onBeforeUnmount,reactive,ref,watch}from'vue';import{ElMessage}from'element-plus';import request from'@/utils/request';import{download}from'@/utils/request';import useUserStore from'@/store/modules/user';
const associationNames:Record<string,string>={LINKED:'已关联',HISTORICAL:'历史未关联',UNIDENTIFIED:'账号未识别'};
const props=defineProps<{kind:string}>(),kind=props.kind,user=useUserStore(),admin=computed(()=>String(user.id)==='1'),can=(p:string)=>actionPermission.has(p);const titles:Record<string,string>={operation:'操作日志',login:'登录日志',runtime:'系统运行日志',config:'日志配置'},roots:Record<string,string>={operation:'/monitor/operlog',login:'/monitor/logininfor',runtime:'/monitor/runtime-log'},permissions:Record<string,string>={operation:'monitor:operlog',login:'monitor:logininfor',runtime:'monitor:runtime-log'};const detailPermission=permissions[kind]+':query',exportPermission=permissions[kind]+':export';const results:Record<string,string>={SUCCESS:'成功',BUSINESS_REJECTED:'业务拒绝',VALIDATION_REJECTED:'校验失败',ACCESS_DENIED:'无权限',SYSTEM_ERROR:'系统异常'};
let disposed=false,listEpoch=0,logDetailEpoch=0;const logDetailLoading=ref(false),logDetailTargetId=ref<string|number>('');
function invalidateLogDetail(){logDetailEpoch++;logDetailLoading.value=false;detail.value={};detailOpen.value=false}
const loadedFilters=ref<string|null>(null);onBeforeUnmount(()=>{disposed=true;listEpoch++;actorEpoch++;logDetailEpoch++});
const factories=ref<any[]>([]),exporting=ref(false),appliedFilters=ref<Record<string,any>>({});
const query=reactive<Record<string,any>>({pageNum:1,pageSize:16}),range=ref<string[]|null>([]),rows=ref<any[]>([]),total=ref(0),loading=ref(false),detailOpen=ref(false),detail=ref<Record<string,any>>({}),config=reactive<Record<string,any>>({}),history=ref<any[]>([]);
const c=(label:string,key:string,width?:number)=>({label,key,width});const columns=kind==='operation'?[c('时间','operTime',155),c('工厂','factoryName'),c('操作人','actorName'),c('模块','title'),c('操作类型','actionCode'),c('业务单号','businessCode',150),c('结果','resultCode'),c('耗时(ms)','costTime',90),c('追踪ID','traceId',245)]:kind==='login'?[c('账号','userName'),c('关联状态','associationStatus',130),c('时间','loginTime',155),c('结果','status'),c('原因','msg',220),c('来源IP','ipaddr'),c('浏览器','browser'),c('追踪ID','traceId',245)]:[c('时间','eventTime',155),c('级别','level',70),c('服务','service'),c('组件','component',180),c('事件','eventType'),c('摘要','summary',240),c('追踪ID','traceId',245)];
const fieldNames:Record<string,string>={operParam:'请求摘要',jsonResult:'响应摘要',changesJson:'字段变更（前后快照）',errorMsg:'失败原因',traceId:'追踪ID',businessCode:'业务单号',detailJson:'技术定位',actorName:'操作人',factoryName:'工厂'};const configFields=[{key:'operationDays',label:'操作日志保留（天）'},{key:'loginDays',label:'登录日志保留（天）'},{key:'runtimeDays',label:'运行日志保留（天）'},{key:'fileDays',label:'运行文件保留（天）'},{key:'archiveDays',label:'审计归档保留（天）'},{key:'slowRequestMs',label:'慢请求阈值(ms)'},{key:'slowSqlMs',label:'慢SQL阈值(ms)'}];
const actorOptions=ref<{id:string;name:string}[]>([]),actorsLoading=ref(false),actorsMore=ref(false);let actorEpoch=0,actorPage=1,actorKeyword='';
async function searchActors(keyword:string,append=false){const current=++actorEpoch;actorsLoading.value=true;const page=append?actorPage+1:1;actorKeyword=keyword;try{const response=await request({url:roots[kind]+'/actors',params:{keyword,pageNum:page,factoryId:query.factoryId}}) as unknown as {rows:{id:string;name:string}[];hasMore:boolean;factories:any[]};if(current!==actorEpoch)return;const selected=actorOptions.value.find(p=>p.id===query.actorId);const next=append?[...actorOptions.value,...response.rows]:response.rows;if(selected&&!next.some(p=>p.id===selected.id))next.unshift(selected);actorOptions.value=[...new Map(next.map(p=>[p.id,p])).values()];actorsMore.value=response.hasMore;actorPage=page;factories.value=response.factories??[]}catch{if(current===actorEpoch){actorsMore.value=false}}finally{if(current===actorEpoch)actorsLoading.value=false}}
function actorFactoryChanged(){delete query.actorId;actorOptions.value=[];actorsMore.value=false;void searchActors('')}
function draftParams(){const result:Record<string,any>={...query,startTime:range.value?.[0],endTime:range.value?.[1]};delete result.pageNum;delete result.pageSize;return Object.fromEntries(Object.entries(result).filter(([,v])=>v!==undefined&&v!==null&&v!==''))}
function params(){return{...appliedFilters.value,pageNum:query.pageNum,pageSize:query.pageSize}}
function applyFilters(){if(range.value?.length===2&&range.value[0]>range.value[1]){ElMessage.warning('开始时间不能晚于结束时间');return}appliedFilters.value=draftParams();query.pageNum=1;load()}
function resetFilters(){for(const key of Object.keys(query))if(!['pageNum','pageSize'].includes(key))delete query[key];range.value=[];if(kind==='operation'||kind==='login')actorFactoryChanged();applyFilters()}
async function load(){if(disposed)return;invalidateLogDetail();const epoch=++listEpoch,snapshot=params();loading.value=true;loadedFilters.value=null;try{if(kind==='config'){Object.assign(config,(await request({url:'/monitor/log-config'})).data);configFields.forEach(f=>config[f.key]=Number(config[f.key]));history.value=(await request({url:'/monitor/log-config/cleanup-history'})).data;}else{const r=await request({url:roots[kind]+'/list',params:snapshot});if(epoch!==listEpoch)return;rows.value=r.rows;total.value=Number(r.total);const {pageNum,pageSize,...filters}=snapshot;loadedFilters.value=JSON.stringify(filters)}}catch{if(epoch===listEpoch){rows.value=[];total.value=0}}finally{if(epoch===listEpoch)loading.value=false}}
async function view(row:any){if(disposed)return;detailOpen.value=false;const epoch=++logDetailEpoch,id=row.id||row.operId;logDetailTargetId.value=id;detail.value={};logDetailLoading.value=true;try{const response=await request({url:roots[kind]+'/'+id});if(disposed||epoch!==logDetailEpoch)return;detail.value=response.data;detailOpen.value=true}catch{if(!disposed&&epoch===logDetailEpoch){detail.value={};ElMessage.error('日志详情加载失败，请重新选择')}}finally{if(!disposed&&epoch===logDetailEpoch)logDetailLoading.value=false}}
watch(detailOpen,open=>{if(!open){logDetailEpoch++;detail.value={};logDetailLoading.value=false}},{flush:'sync'})
function format(value:any){if(typeof value==='string'){try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}return JSON.stringify(value,null,2)}async function copyTrace(){if(!logDetailLoading.value&&detail.value.traceId){try{await copyText(detail.value.traceId);ElMessage.success('追踪ID已复制')}catch{ElMessage.warning('复制失败，请手动选择追踪ID')}}}async function exportLogs(){if(exporting.value||loading.value||loadedFilters.value!==JSON.stringify(appliedFilters.value))return;if(JSON.stringify(draftParams())!==JSON.stringify(appliedFilters.value)){ElMessage.warning('筛选条件已修改，请先点击查询');return}exporting.value=true;try{await download(roots[kind]+'/export',params(),'日志.xlsx')}finally{exporting.value=false}}async function saveConfig(){await request({url:'/monitor/log-config',method:'put',data:config});ElMessage.success('配置已保存');await load()}onMounted(async()=>{if(kind==='operation'||kind==='login')await searchActors('');await load()})
</script><style scoped>.log-page{min-width:0;max-width:100%;box-sizing:border-box;padding:20px;min-height:calc(100vh - 82px)}h2{font-size:20px;margin:0 0 20px}.log-toolbar{display:flex;align-items:center;column-gap:12px;row-gap:10px;flex-wrap:wrap;min-width:0;max-width:100%;margin-bottom:16px}.filters{display:contents}.filters>.el-input,.filters>.el-select{width:180px;flex:0 0 min(180px,100%);min-width:0;max-width:100%}.filters>.log-actor-select{width:320px;flex-basis:min(320px,100%)}.filters :deep(.log-filter-date){width:360px;min-width:0;max-width:100%;flex:0 0 min(360px,100%);height:35px;min-height:35px;box-sizing:border-box}@media(max-width:480px){.filters>.el-input,.filters>.el-select,.filters :deep(.log-filter-date){width:100%;flex-basis:100%;min-width:0;max-width:100%}}.el-pagination{justify-content:center;margin-top:24px;max-width:100%;height:auto;flex-wrap:wrap;gap:8px}.log-details{display:grid;grid-template-columns:150px 1fr;gap:12px;max-height:65vh;overflow:auto}.log-details pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:0;font-size:13px}</style>
